function calculateSolarPayback() {
  var cost = parseFloat(document.getElementById('initialCost').value) || 0;
  var watts = parseFloat(document.getElementById('panelWatts').value) || 0;
  var sunHours = parseFloat(document.getElementById('sunHours').value) || 0;
  var rate = parseFloat(document.getElementById('electricityRate').value) || 0;
  var loss = parseFloat(document.getElementById('systemLoss').value) || 0;
  var lifespan = parseFloat(document.getElementById('expectedLifespan').value) || 10;

  var eff = (100 - loss) / 100;
  var dailyWh = watts * sunHours * eff;
  var annualKwh = (dailyWh * 365) / 1000;
  var annualSaving = Math.round(annualKwh * rate);

  var paybackYears = annualSaving > 0 ? (cost / annualSaving) : Infinity;
  var lifetimeSaving = Math.round(annualSaving * lifespan);
  var netBenefit = lifetimeSaving - cost;

  var headlineText = '';
  if (!isFinite(paybackYears) || paybackYears > 50) {
    headlineText = '元を取るのは極めて困難（節電のみでの回収は不向き）';
  } else if (paybackYears <= lifespan) {
    headlineText = '寿命内の「約' + paybackYears.toFixed(1) + '年」で元が取れます！';
  } else {
    headlineText = '元を取るには「約' + paybackYears.toFixed(1) + '年」必要（寿命' + lifespan + '年を超過）';
  }

  var netClass = netBenefit >= 0 ? '#16a34a' : '#dc2626';
  var netPrefix = netBenefit >= 0 ? '+' : '';

  var html = '<div class="result-headline">結論：<strong>' + headlineText + '</strong></div>';
  html += '<div class="metrics-row">';
  html += '  <div class="metric-card"><span>年間発電量（実効）</span><strong>' + annualKwh.toFixed(1) + ' <small>kWh</small></strong><small>1日平均 ' + (dailyWh).toFixed(0) + ' Wh</small></div>';
  html += '  <div class="metric-card"><span>年間の電気代節約額</span><strong>約 ' + annualSaving.toLocaleString() + ' <small>円</small></strong><small>単価 ' + rate + '円/kWh換算</small></div>';
  html += '  <div class="metric-card"><span>回収までの年数</span><strong>' + (isFinite(paybackYears) ? paybackYears.toFixed(1) + ' <small>年</small>' : '測定不能') + '</strong><small>初期費用 ' + cost.toLocaleString() + '円</small></div>';
  html += '  <div class="metric-card"><span>' + lifespan + '年間の生涯収支</span><strong style="color:' + netClass + ';">' + netPrefix + netBenefit.toLocaleString() + ' <small>円</small></strong><small>（節電総額 - 初期費用）</small></div>';
  html += '</div>';

  document.getElementById('calcResult').innerHTML = html;
}
document.addEventListener('DOMContentLoaded', calculateSolarPayback);
